use clap::{Parser, Subcommand};

mod commands;

#[derive(Parser)]
#[command(name = "x-vcs", about = "A minimal version control system")]
pub struct Cli {
    #[command(subcommand)]
    pub cmd: Commands,
}

#[derive(Subcommand)]
pub enum Commands {
    Init,
    Add { files: Vec<String> },
    Commit {
        #[arg(short, long)]
        message: String,
    },
    Log,
    CatFile { hash: String },
    LsFiles,
    Checkout { hash: String },
    Status,
    Diff {
        hash1: String,
        hash2: String,
    },
    Tag {
        name: String,
        hash: String,
    },
    Tags,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    match cli.cmd {
        Commands::Init => commands::init()?,
        Commands::Add { files } => commands::add(&files)?,
        Commands::Commit { message } => commands::commit(&message)?,
        Commands::Log => commands::log()?,
        Commands::CatFile { hash } => commands::cat_file(&hash)?,
        Commands::LsFiles => commands::ls_files()?,
        Commands::Checkout { hash } => commands::checkout(&hash)?,
        Commands::Status => commands::status()?,
        Commands::Diff { hash1, hash2 } => commands::diff(&hash1, &hash2)?,
        Commands::Tag { name, hash } => commands::tag(&name, &hash)?,
        Commands::Tags => commands::tags()?,
    }

    Ok(())
}
