use sha2::{Digest, Sha256};

use crate::Error;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ObjectType {
    Blob,
    Tree,
    Commit,
}

impl std::fmt::Display for ObjectType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ObjectType::Blob => write!(f, "blob"),
            ObjectType::Tree => write!(f, "tree"),
            ObjectType::Commit => write!(f, "commit"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Commit {
    pub tree_hash: String,
    pub parent_hash: Option<String>,
    pub message: String,
    pub timestamp: String,
}

#[derive(Debug, Clone)]
pub struct TreeEntry {
    pub hash: String,
    pub mode: u32,
    pub path: String,
}

pub fn serialize_object(type_: ObjectType, content: &str) -> String {
    format!("{}\n{}", type_, content)
}

pub fn hash_object(type_: ObjectType, content: &str) -> String {
    let serialized = serialize_object(type_, content);
    let mut hasher = Sha256::new();
    hasher.update(serialized.as_bytes());
    hex::encode(hasher.finalize())
}

pub fn parse_object(data: &str) -> Result<(ObjectType, String), Error> {
    let mut parts = data.splitn(2, '\n');
    let type_str = parts.next().ok_or_else(|| Error::InvalidFormat("empty object data".into()))?;
    let content = parts.next().ok_or_else(|| Error::InvalidFormat("missing object content".into()))?;

    let type_ = match type_str {
        "blob" => ObjectType::Blob,
        "tree" => ObjectType::Tree,
        "commit" => ObjectType::Commit,
        _ => return Err(Error::InvalidFormat(format!("unknown object type: {}", type_str))),
    };

    Ok((type_, content.to_string()))
}

impl Commit {
    pub fn parse(content: &str) -> Result<Self, Error> {
        let mut tree_hash = None;
        let mut parent_hash = None;
        let mut message = String::new();
        let mut timestamp = None;

        for line in content.lines() {
            if line.starts_with("tree ") {
                tree_hash = Some(line[5..].to_string());
            } else if line.starts_with("parent ") {
                parent_hash = Some(line[7..].to_string());
            } else if line.starts_with("message ") {
                message = line[8..].to_string();
            } else if line.starts_with("timestamp ") {
                timestamp = Some(line[10..].to_string());
            }
        }

        Ok(Commit {
            tree_hash: tree_hash.ok_or_else(|| Error::InvalidFormat("missing tree hash".into()))?,
            parent_hash,
            message,
            timestamp: timestamp.ok_or_else(|| Error::InvalidFormat("missing timestamp".into()))?,
        })
    }

    pub fn serialize(&self) -> String {
        let mut lines = Vec::new();
        lines.push(format!("tree {}", self.tree_hash));
        if let Some(ref parent) = self.parent_hash {
            lines.push(format!("parent {}", parent));
        }
        lines.push(format!("message {}", self.message));
        lines.push(format!("timestamp {}", self.timestamp));
        lines.join("\n")
    }
}

pub fn parse_tree(content: &str) -> Result<Vec<TreeEntry>, Error> {
    let mut entries = Vec::new();
    for line in content.lines() {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.splitn(3, ' ').collect();
        if parts.len() != 3 {
            return Err(Error::InvalidFormat(format!("invalid tree entry: {}", line)));
        }
        let mode = parts[0]
            .parse::<u32>()
            .map_err(|_| Error::InvalidFormat(format!("invalid mode: {}", parts[0])))?;
        entries.push(TreeEntry {
            hash: parts[1].to_string(),
            mode,
            path: parts[2].to_string(),
        });
    }
    Ok(entries)
}

pub fn serialize_tree(entries: &[TreeEntry]) -> String {
    entries
        .iter()
        .map(|e| format!("{} {} {}", e.mode, e.hash, e.path))
        .collect::<Vec<_>>()
        .join("\n")
}

