use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

use crate::models::*;
use crate::Error;

pub struct Store {
    root: PathBuf,
}

fn validate_hash(hash: &str) -> Result<(), Error> {
    if hash.len() != 64 {
        return Err(Error::InvalidFormat(format!(
            "hash must be 64 characters, got {}",
            hash.len()
        )));
    }
    if !hash.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err(Error::InvalidFormat(format!("hash contains non-hex characters: {}", hash)));
    }
    Ok(())
}

fn validate_tag_name(name: &str) -> Result<(), Error> {
    if name.is_empty() {
        return Err(Error::InvalidFormat("tag name must not be empty".into()));
    }
    if name.contains('/') || name.contains('\\') {
        return Err(Error::InvalidFormat(format!("tag name must not contain path separators: {}", name)));
    }
    Ok(())
}

impl Store {
    pub fn new(root: &Path) -> Result<Self, Error> {
        let vcs_dir = root.join(".vcs");
        if !vcs_dir.exists() {
            return Err(Error::NotFound(format!(".vcs directory not found at {}", vcs_dir.display())));
        }

        fs::create_dir_all(vcs_dir.join("objects"))?;
        fs::create_dir_all(vcs_dir.join("tags"))?;

        Ok(Store { root: vcs_dir })
    }

    pub fn write_object(&self, type_: ObjectType, content: &str) -> Result<String, Error> {
        let hash = hash_object(type_, content);
        let path = self.object_path(&hash);

        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }

        let serialized = serialize_object(type_, content);
        fs::write(&path, &serialized)?;

        Ok(hash)
    }

    pub fn read_object(&self, hash: &str) -> Result<(ObjectType, String), Error> {
        validate_hash(hash)?;

        let path = self.object_path(hash);
        if !path.exists() {
            return Err(Error::NotFound(format!("object {} not found", hash)));
        }

        let data = fs::read_to_string(&path)?;
        parse_object(&data)
    }

    pub fn write_head(&self, hash: &str) -> Result<(), Error> {
        validate_hash(hash)?;

        let head_path = self.root.join("HEAD");
        fs::write(&head_path, hash)?;

        Ok(())
    }

    pub fn read_head(&self) -> Result<String, Error> {
        let head_path = self.root.join("HEAD");
        if !head_path.exists() {
            return Err(Error::NotFound("HEAD not found".into()));
        }

        let content = fs::read_to_string(&head_path)?;
        Ok(content.trim().to_string())
    }

    pub fn write_tag(&self, name: &str, hash: &str) -> Result<(), Error> {
        validate_tag_name(name)?;
        validate_hash(hash)?;

        let tag_path = self.root.join("tags").join(name);
        fs::write(&tag_path, hash)?;

        Ok(())
    }

    pub fn read_tags(&self) -> Result<HashMap<String, String>, Error> {
        let tags_dir = self.root.join("tags");
        if !tags_dir.exists() {
            return Ok(HashMap::new());
        }

        let mut tags = HashMap::new();
        for entry in fs::read_dir(&tags_dir)? {
            let entry = entry?;
            if entry.file_type()?.is_file() {
                let name = entry.file_name().to_string_lossy().to_string();
                let hash = fs::read_to_string(entry.path())?.trim().to_string();
                tags.insert(name, hash);
            }
        }

        Ok(tags)
    }

    pub fn object_path(&self, hash: &str) -> PathBuf {
        let prefix = &hash[..2];
        self.root.join("objects").join(prefix).join(&hash[2..])
    }
}

