        let (type_, content) = store.read_object(&hash)?;
        if type_ != ObjectType::Commit {
            break;
        }

        let commit = Commit::parse(&content)?;
        println!("{} {}", hash, commit.message);

        if let Some(ref parent) = commit.parent_hash {
            hash = parent.clone();
        } else {
            break;
        }
    }

    Ok(())
}

pub fn cat_file(dir: &Path, store: &Store, hash: &str) -> Result<(), Box<dyn std::error::Error>> {
    let (type_, content) = store.read_object(hash)?;
    println!("{}: {}", type_, content);
    Ok(())
}

pub fn ls_files(dir: &Path, store: &Store) -> Result<(), Box<dyn std::error::Error>> {
    let head_hash = store.read_head()?;
    let (type_, content) = store.read_object(&head_hash)?;

    if type_ != ObjectType::Commit {
        return Err(Error::InvalidFormat("HEAD does not point to a commit".into()).into());
    }

    let commit = Commit::parse(&content)?;
    let (type_, tree_content) = store.read_object(&commit.tree_hash)?;

    if type_ != ObjectType::Tree {
        return Err(Error::InvalidFormat("commit tree is not a tree object".into()).into());
    }

    let entries = parse_tree(&tree_content)?;
    for entry in &entries {
        println!("{} {}", entry.mode, entry.path);
    }

    Ok(())
}

pub fn checkout(dir: &Path, store: &Store, hash: &str) -> Result<(), Box<dyn std::error::Error>> {
    let (type_, content) = store.read_object(hash)?;

    if type_ != ObjectType::Commit {
        return Err(Error::InvalidFormat("not a commit object".into()).into());
    }

    let commit = Commit::parse(&content)?;
    let (type_, tree_content) = store.read_object(&commit.tree_hash)?;

    if type_ != ObjectType::Tree {
        return Err(Error::InvalidFormat("commit tree is not a tree object".into()).into());
    }

    let entries = parse_tree(&tree_content)?;

    // Write files to working directory
    for entry in &entries {
        let (type_, content) = store.read_object(&entry.hash)?;
        if type_ != ObjectType::Blob {
            continue; // skip non-blob entries (subtrees)
        }

        let path = dir.join(&entry.path);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(&path, &content)?;
    }

    // Update HEAD
    store.write_head(hash)?;

    Ok(())
}

pub fn status(dir: &Path, store: &Store) -> Result<(), Box<dyn std::error::Error>> {
    let index = read_index(dir)?;

    // Check for modified files (in index but content changed)
    let mut modified = Vec::new();
    for (path, hash) in &index {
        let full_path = dir.join(path);
        if full_path.exists() {
            let content = fs::read_to_string(&full_path)?;
            let current_hash = hash_object(ObjectType::Blob, &content);
            if current_hash != *hash {
                modified.push(path.clone());
            }
        }
    }

    // Check for untracked files (in working dir but not in index)
    let mut untracked = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.flatten() {
            let name = entry.file_name().to_string_lossy().to_string();
            if !name.starts_with('.') && entry.file_type().map(|ft| ft.is_file()).unwrap_or(false) {
                if !index.contains_key(&name) {
                    untracked.push(name);
                }
            }
        }
    }

    if modified.is_empty() && untracked.is_empty() {
        println!("nothing to commit, working tree clean");
    } else {
        if !modified.is_empty() {
            println!("modified:");
            for path in &modified {
                println!("  {}", path);
            }
        }
        if !untracked.is_empty() {
            println!("untracked:");
            for path in &untracked {
                println!("  {}", path);
            }
        }
    }

    Ok(())
}

pub fn diff(dir: &Path, store: &Store, hash1: &str, hash2: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let (type_, content) = store.read_object(hash1)?;
    if type_ != ObjectType::Commit {
        return Err(Error::InvalidFormat("not a commit object".into()).into());
    }

    let commit1 = Commit::parse(&content)?;
    let tree1_entries = get_tree_entries(store, &commit1.tree_hash)?;

    if let Some(h2) = hash2 {
        let (type_, content) = store.read_object(h2)?;
        if type_ != ObjectType::Commit {
            return Err(Error::InvalidFormat("not a commit object".into()).into());
        }

        let commit2 = Commit::parse(&content)?;
        let tree2_entries = get_tree_entries(store, &commit2.tree_hash)?;

        // Compare trees
        let mut set1: HashMap<String, String> = tree1_entries.iter().map(|e| (e.path.clone(), e.hash.clone())).collect();
        let mut set2: HashMap<String, String> = tree2_entries.iter().map(|e| (e.path.clone(), e.hash.clone())).collect();

        // Files added in hash2
        for (path, hash) in &set2 {
            if !set1.contains_key(path) {
                println!("added: {}", path);
            } else if set1[path] != *hash {
                println!("modified: {}", path);
            }
        }

        // Files removed in hash2
        for (path, _) in &set1 {
            if !set2.contains_key(path) {
                println!("removed: {}", path);
            }
        }
    } else {
        // Diff against working directory (index)
        let index = read_index(dir)?;

        for (path, hash) in &index {
            let full_path = dir.join(path);
            if !full_path.exists() {
                println!("removed: {}", path);
            } else {
                let content = fs::read_to_string(&full_path)?;
                let current_hash = hash_object(ObjectType::Blob, &content);
                if current_hash != *hash {
                    println!("modified: {}", path);
                }
            }
        }

        // Untracked files
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                let name = entry.file_name().to_string_lossy().to_string();
                if !name.starts_with('.') && entry.file_type().map(|ft| ft.is_file()).unwrap_or(false) {
                    if !index.contains_key(&name) {
                        println!("untracked: {}", name);
                    }
                }
            }
        }
    }

    Ok(())
}

pub fn tag(dir: &Path, store: &Store, name: &str, hash: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let target_hash = hash.unwrap_or_else(|| store.read_head().unwrap());
    store.write_tag(name, target_hash)?;
    Ok(())
}

pub fn tags(dir: &Path, store: &Store) -> Result<(), Box<dyn std::error::Error>> {
    let tag_map = store.read_tags()?;
    for (name, hash) in &tag_map {
        println!("{} {}", name, hash);
    }
    Ok(())
}

// Helper: read index file (format: "hash path" per line)
pub fn read_index(dir: &Path) -> Result<HashMap<String, String>, Error> {
    let index_path = dir.join(".vcs").join(INDEX_FILE);
    if !index_path.exists() {
        return Ok(HashMap::new());
    }

    let content = fs::read_to_string(&index_path)?;
    let mut index = HashMap::new();

    for line in content.lines() {
        if line.is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.splitn(2, ' ').collect();
        if parts.len() == 2 {
            index.insert(parts[1].to_string(), parts[0].to_string());
        }
    }

    Ok(index)
}

fn write_index(dir: &Path, index: &HashMap<String, String>) -> Result<(), Error> {
    let index_path = dir.join(".vcs").join(INDEX_FILE);

    let content: String = index.iter()
        .map(|(path, hash)| format!("{} {}", hash, path))
        .collect::<Vec<_>>()
        .join("\n");

    fs::write(&index_path, content)?;
    Ok(())
}

fn get_tree_entries(store: &Store, tree_hash: &str) -> Result<Vec<TreeEntry>, Error> {
    let (type_, content) = store.read_object(tree_hash)?;
    if type_ != ObjectType::Tree {
        return Err(Error::InvalidFormat("not a tree object".into()));
    }
    parse_tree(&content)
}
