    #[command(subcommand)]
    pub cmd: Commands,
}

#[derive(Subcommand)]
pub enum Commands {
    Init,
    Add { files: Vec<String> },
    Commit {
        #[arg(short, long)]
        message: String,
    },
    Log,
    CatFile { hash: String },
    LsFiles,
    Checkout { hash: String },
    Status,
    Diff {
        hash1: String,
        #[arg(required = false)]
        hash2: Option<String>,
    },
    Tag {
        name: String,
        #[arg(required = false)]
        hash: Option<String>,
    },
    Tags,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();
    let dir = env::current_dir()?;

    match cli.cmd {
        Commands::Init => commands::init(&dir)?,
        Commands::Add { files } => {
            let store = Store::new(&dir)?;
            for file in &files {
                commands::add(&dir, &store, file)?;
            }
        }
        Commands::Commit { message } => {
            let store = Store::new(&dir)?;
            commands::commit(&dir, &store, &message)?;
        }
        Commands::Log => {
