        Commands::CatFile { hash } => {
            let store = Store::new(&dir)?;
            commands::cat_file(&dir, &store, &hash)?;
        }
        Commands::LsFiles => {
            let store = Store::new(&dir)?;
            commands::ls_files(&dir, &store)?;
        }
        Commands::Checkout { hash } => {
            let store = Store::new(&dir)?;
            commands::checkout(&dir, &store, &hash)?;
        }
        Commands::Status => {
            let store = Store::new(&dir)?;
            commands::status(&dir, &store)?;
        }
        Commands::Diff { hash1, hash2 } => {
            let store = Store::new(&dir)?;
            commands::diff(&dir, &store, &hash1, hash2.as_deref())?;
        }
        Commands::Tag { name, hash } => {
            let store = Store::new(&dir)?;
