#[test]
fn test_checkout() {
    let dir = temp_dir();
    commands::init(&dir).unwrap();
    let store = Store::new(&dir).unwrap();

    // First commit with one file
    fs::write(dir.join("a.txt"), "aaa").unwrap();
    commands::add(&dir, &store, "a.txt").unwrap();
    let first_hash = store.read_head().unwrap();

    // Second commit with two files
    fs::write(dir.join("b.txt"), "bbb").unwrap();
    commands::add(&dir, &store, "b.txt").unwrap();
    commands::commit(&dir, &store, "add b").unwrap();

    // Checkout first commit
    commands::checkout(&dir, &store, &first_hash).unwrap();

    // a.txt should exist, b.txt should not
    assert!(dir.join("a.txt").exists());
    assert!(!dir.join("b.txt").exists());

    cleanup(&dir);
}

